/// How a band's 5-segment meter is drawn.
enum PlinthMeterStyle { solid, dashed, outlined }

/// Delivery-risk keys with their meter step (1–5; 0 = no band).
///
/// Band names, frequencies and reasons are server copy, not tokens.
enum PlinthRiskKey {
  low(step: 1, meter: PlinthMeterStyle.solid),
  moderate(step: 2, meter: PlinthMeterStyle.solid),
  elevated(step: 3, meter: PlinthMeterStyle.solid),
  high(step: 4, meter: PlinthMeterStyle.solid),
  severe(step: 5, meter: PlinthMeterStyle.solid),
  limited(step: 0, meter: PlinthMeterStyle.dashed),
  notScored(step: 0, meter: PlinthMeterStyle.outlined);

  const PlinthRiskKey({required this.step, required this.meter});

  /// Filled segments of the 5-segment meter.
  final int step;

  /// How the meter is drawn.
  final PlinthMeterStyle meter;
}

/// The three colours of one risk band.
@immutable
class PlinthBandColors {
  const PlinthBandColors({
    required this.ink,
    required this.fill,
    required this.text,
  });

  /// Meter segments, icon-array cells, hatch stripes.
  final Color ink;

  /// Chip and panel background.
  final Color fill;

  /// The band name set in colour (Low and Moderate use ink on Day).
  final Color text;

  /// Linear interpolation, for theme animations.
  PlinthBandColors lerp(PlinthBandColors other, double t) {
    return PlinthBandColors(
      ink: Color.lerp(ink, other.ink, t)!,
      fill: Color.lerp(fill, other.fill, t)!,
      text: Color.lerp(text, other.text, t)!,
    );
  }
}

